def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    capacity = float(supply) / float(WATER_REQ)

    prev_bids = []
    strong_threat = False
    cheap_lane = False
    desperate_opp = False
    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        pbid = prev.get('bid') if prev else None
        if pbid is not None:
            prev_bids.append(float(pbid))
            if float(pbid) >= 100:
                strong_threat = True
            if float(pbid) <= 25:
                cheap_lane = True
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_opp = True

    alive_count = len(alive)

    if hp <= 2 or no_water_days >= 2:
        if prev_bids:
            target = max(prev_bids) + 3.0
            return float(min(budget, max(78.0, target)))
        return float(min(budget, 85.0))

    if alive_count == 0:
        return float(min(budget, 8.0))

    if capacity >= alive_count:
        if cheap_lane:
            return float(min(budget, 12.0))
        return float(min(budget, 9.0))

    if capacity >= 1.5:
        if strong_threat and hp >= 5 and no_water_days == 0:
            return float(min(budget, 18.0))
        if prev_bids:
            low_prev = min(prev_bids)
            return float(min(budget, max(16.0, low_prev + 2.0)))
        return float(min(budget, 20.0))

    if strong_threat:
        if hp >= 6 and no_water_days == 0 and day < 8:
            return float(min(budget, 14.0))
        if prev_bids:
            target = max(prev_bids) + 2.0
            return float(min(budget, max(72.0, target)))
        return float(min(budget, 76.0))

    if desperate_opp:
        if prev_bids:
            target = max(prev_bids) + 2.0
            return float(min(budget, max(55.0, target)))
        return float(min(budget, 58.0))

    if prev_bids:
        sorted_bids = sorted(prev_bids)
        idx = int(min(len(sorted_bids) - 1, 1))
        anchor = sorted_bids[idx]
        return float(min(budget, max(28.0, anchor + 3.0)))

    return float(min(budget, 30.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Alive opponents
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return min(float(my_status['budget']), DAILY_SALARY * 0.4)

    # Read yesterday trace bids to infer who is pressuring
    prev_bids = []
    prev_hp_after = []
    for opp_id, opp in opponents_status.items():
        if not opp.get('alive', False):
            continue
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            prev_bids.append(float(b))
            prev_hp_after.append(float(prev.get('hp_after', 0.0)))

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Estimate today's required intensity from supply
    # More supply => we can bid less; less supply => bid more.
    if supply <= MIN_SUPPLY:
        supply_factor = 1.0
    elif supply >= MAX_SUPPLY:
        supply_factor = 0.65
    else:
        # linear interpolation between MIN_SUPPLY and MAX_SUPPLY
        supply_factor = 1.0 - (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) * 0.35

    # Identify top yesterday bidder; Cindy likely highest and still alive.
    top_bid = max(prev_bids) if prev_bids else 0.0

    # If someone was bidding extremely high yesterday, they likely secured water.
    # We can undercut to avoid overspending.
    # Target: just enough to beat the second-tier, but not chase the top.
    sorted_prev = sorted(prev_bids, reverse=True)
    second_bid = sorted_prev[1] if len(sorted_prev) > 1 else (sorted_prev[0] if sorted_prev else 0.0)

    # Base bid determined by our health/budget
    if my_hp <= 2:
        base = DAILY_SALARY * 0.85
    elif my_hp <= 4:
        base = DAILY_SALARY * 0.65
    else:
        base = DAILY_SALARY * 0.5

    # If top bidder is very aggressive, we bid around second_bid + small margin scaled by supply.
    # Otherwise, bid more confidently.
    if top_bid >= DAILY_SALARY * 0.9:
        target = (second_bid + 2.0) * supply_factor
    else:
        target = max(second_bid * 0.9 + 1.0, base * supply_factor)

    # Budget-aware cap: never bid more than we can afford
    target = min(target, my_budget)

    # Ensure we bid at least something when supply is tight and we might be at risk.
    if supply <= MIN_SUPPLY and my_hp <= 4:
        floor_bid = min(my_budget, DAILY_SALARY * 0.55)
        target = max(target, floor_bid)

    # If budget is low, bid a smaller fraction.
    if my_budget <= DAILY_SALARY * 0.25:
        target = min(my_budget, DAILY_SALARY * 0.2)

    # Final clamp
    if target < 0.0:
        target = 0.0
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    WATER_REQ = 13

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3:
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            else:
                return min(my_status['budget'], DAILY_SALARY * 0.95)
        else:
            return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))

    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.9)
    else:
        return min(my_status['budget'], DAILY_SALARY * 0.55)

